#define L1_LATENCY 4 // cycles
#define MAIN_MEM_LATENCY 100 // cycles
#define CACHE_LINE_SIZE 64 // bytes

// Strategy: Exploit Spatial Locality (Efficient Cache Utilization)
#define N 100
int matrix[N][N];

// Row-Major Access (C/C++ default layout)
// High hit rate: Sequential access loads neighboring elements into cache line
for (int r = 0; r < N; r++) {
    for (int c = 0; c < N; c++) {
        matrix[r][c] = r + c;
    }
}

// Temporal Locality: Reusing data already in cache (e.g., small loop variables)
int x = matrix[5][5];
x = x * 2; // Data 'x' is quickly reused from L1 cache
